// EDIT THIS LIST: official pages to watch. Use only official government (https) URLs.
const pages = [
  { source: 'State Scholarship Portal (Karnataka)', url: 'https://ssp.postmatric.karnataka.gov.in/', schemeSlug: null },
  { source: 'National Scholarship Portal', url: 'https://scholarships.gov.in/', schemeSlug: 'central-sector-scholarship' },
  { source: 'FRUITS (Karnataka Agriculture)', url: 'https://fruits.karnataka.gov.in/', schemeSlug: 'raitha-vidya-nidhi' }
];
return pages.map((p) => ({ json: p }));

// Compares each page with the last run and builds a signed event when it changed or broke.
// Requires env vars on the n8n server: SAHAAY_WEBHOOK_SECRET and NODE_FUNCTION_ALLOW_BUILTIN=crypto
const crypto = require('crypto');
const state = $getWorkflowStaticData('global');
state.hashes = state.hashes || {};
const secret = $env.SAHAAY_WEBHOOK_SECRET;
if (!secret) throw new Error('Set SAHAAY_WEBHOOK_SECRET on the n8n server');

const pages = $('Pages to watch').all().map((i) => i.json);
const responses = $input.all();
const out = [];
const today = new Date().toISOString().slice(0, 10);

responses.forEach((res, index) => {
  const page = pages[index];
  const status = res.json.statusCode;
  const body = typeof res.json.body === 'string' ? res.json.body : JSON.stringify(res.json.body ?? '');
  // Strip scripts, styles and tags so rotating tokens/ads don't trigger false alarms.
  const text = body
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const hash = crypto.createHash('sha256').update(text).digest('hex');

  let event = null;
  if (!status || status >= 400) {
    event = { eventType: 'link_broken', title: `Official page not reachable (HTTP ${status ?? 'error'}): ${page.source}`, key: `broken:${page.url}:${today}` };
  } else if (state.hashes[page.url] && state.hashes[page.url] !== hash) {
    event = { eventType: 'page_changed', title: `Official page changed: ${page.source}`, key: `changed:${page.url}:${hash.slice(0, 16)}` };
  }
  if (status && status < 400) state.hashes[page.url] = hash;
  if (!event) return;

  const payload = {
    idempotencyKey: event.key,
    source: page.source,
    sourceUrl: page.url,
    eventType: event.eventType,
    title: event.title,
    details: 'Detected automatically by n8n. Open the page, check what changed (new scheme, deadline, benefit or eligibility) and update the scheme record if needed.',
    ...(page.schemeSlug ? { schemeSlug: page.schemeSlug } : {})
  };
  const body2 = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body2}`).digest('hex');
  out.push({ json: { body: body2, timestamp, signature } });
});

return out;
